<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('users.manage');$pdo=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();try{$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$role=(int)($_POST['role_id']??0);$company=(int)($_POST['company_id']??0)?:null;$branch=(int)($_POST['branch_id']??0)?:null;$status=in_array($_POST['status']??'active',['active','disabled'],true)?$_POST['status']:'active';$password=$_POST['password']??'';if(mb_strlen($name)<2||!preg_match('/^[A-Za-z0-9_.-]{3,100}$/',$username)||!$role)throw new RuntimeException('تحقق من الاسم واسم المستخدم والدور.');if(($user['role']??'')!=='super_admin')throw new RuntimeException('إدارة الحسابات محصورة بمدير النظام الرئيسي.');if($branch&&$company){$q=$pdo->prepare('SELECT COUNT(*) FROM branches WHERE id=? AND company_id=?');$q->execute([$branch,$company]);if(!(int)$q->fetchColumn())throw new RuntimeException('الفرع لا يتبع الشركة المختارة.');}
if($id){$sql='UPDATE users SET role_id=?,company_id=?,branch_id=?,name=?,username=?,status=?';$args=[$role,$company,$branch,$name,$username,$status];if($password!==''){if(strlen($password)<12)throw new RuntimeException('كلمة المرور يجب ألا تقل عن 12 حرفاً.');$sql.=',password_hash=?';$args[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$args[]=$id;$pdo->prepare($sql)->execute($args);admin_log($pdo,$user,'user.updated','user',$id,'تعديل حساب موظف');}
else{if(strlen($password)<12)throw new RuntimeException('كلمة المرور يجب ألا تقل عن 12 حرفاً.');$email=trim($_POST['email']??'')?:null;$phone=trim($_POST['phone']??'')?:null;$pdo->prepare('INSERT INTO users(role_id,company_id,branch_id,name,username,email,phone,password_hash,status) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$role,$company,$branch,$name,$username,$email,$phone,password_hash($password,PASSWORD_DEFAULT),$status]);admin_log($pdo,$user,'user.created','user',(int)$pdo->lastInsertId(),'إنشاء حساب موظف');}redirect('/admin/users.php?saved=1');}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT id,role_id,company_id,branch_id,name,username,email,phone,status FROM users WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}
$roles=$pdo->query('SELECT id,name FROM roles ORDER BY id')->fetchAll();$companies=$pdo->query('SELECT id,name FROM companies ORDER BY name')->fetchAll();$branches=$pdo->query('SELECT id,name,company_id FROM branches ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT u.id,u.name,u.username,u.status,r.name role_name,c.name company_name FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN companies c ON c.id=u.company_id ORDER BY u.id DESC LIMIT 300')->fetchAll();
admin_page_start('إدارة الموظفين والحسابات',$user);if($error)echo '<p class="notice danger">'.e($error).'</p>';if(isset($_GET['saved']))echo '<p class="notice">تم حفظ حساب الموظف.</p>';
$v=fn($k)=>e($edit[$k]??'');echo '<section class="panel"><h2>'.($edit?'تعديل حساب':'إنشاء حساب موظف').'</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><label>الاسم<input name="name" required value="'.$v('name').'"></label><label>اسم المستخدم<input name="username" required value="'.$v('username').'"></label><label>البريد<input type="email" name="email" value="'.$v('email').'"></label><label>الهاتف<input name="phone" value="'.$v('phone').'"></label><label>الدور<select name="role_id" required>';foreach($roles as $r)echo '<option value="'.(int)$r['id'].'" '.((int)($edit['role_id']??0)===(int)$r['id']?'selected':'').'>'.e($r['name']).'</option>';echo '</select></label><label>الشركة<select name="company_id"><option value="">بدون شركة</option>';foreach($companies as $c)echo '<option value="'.(int)$c['id'].'" '.((int)($edit['company_id']??0)===(int)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select></label><label>الفرع<select name="branch_id"><option value="">بدون فرع</option>';foreach($branches as $b)echo '<option value="'.(int)$b['id'].'" '.((int)($edit['branch_id']??0)===(int)$b['id']?'selected':'').'>'.e($b['name']).'</option>';echo '</select></label><label>كلمة المرور '.($edit?'(اتركها فارغة دون تغيير)':'').'<input type="password" name="password" '.($edit?'':'required').' minlength="12"></label><label>الحالة<select name="status"><option value="active">نشط</option><option value="disabled" '.(($edit['status']??'')==='disabled'?'selected':'').'>معطل</option></select></label><button class="btn btn-primary">حفظ الحساب</button></form></section><section class="panel"><table><thead><tr><th>الموظف</th><th>المستخدم</th><th>الدور</th><th>الشركة</th><th>الحالة</th><th></th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['username']).'</td><td>'.e($r['role_name']).'</td><td>'.e($r['company_name']??'—').'</td><td>'.e($r['status']).'</td><td><a class="admin-link" href="/admin/users.php?edit='.(int)$r['id'].'">تعديل</a></td></tr>';echo '</tbody></table></section>';admin_page_end();
